            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "Mire veja: sabe por que é que eu não purgo remorso? Acho que o que não deixa é a minha boa memória. A luzinha dos santos-arrependidos se acende é no escuro.", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "Como é que posso com este mundo? A vida é ingrata no macio de si; mas transtraz a esperança mesmo do macio do meio do fel do desespero. Ao que, este mundo é muito misturado...", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "O que tivesse de ser, somente sendo. Não era nem o Hermógenes, era um estado de lei, nem dele não era, eu cumpria, todos cumpriam.", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "Ao que naquele tempo, eu não sabia pensar com poder. Aprendendo eu estava? Não sabia pensar com poder - por isso matava.", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "O correr da vida embrulha tudo, a vida é assim: esquenta e esfria, aperta e daí afrouxa, sossega e depois desinquieta. O que ela quer da gente é coragem.", Author = "Guimarães Rosa" },
