            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "Qualquer amor é um pouquinho de saúde, um descanso na loucura.", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "Pão ou pães é questão de opiniães.", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "Porque a cabeça da gente é uma só, e as coisas que há e que estão para haver são demais de muitas, muito maiores diferentes, e a gente tem de necessitar de aumentar a cabeça, para o total.", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "Mestre não é quem sempre ensina, mas quem de repente aprende.", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "Que Deus existe, sim, devagarinho, depressa. Ele existe - mas quase só por intermédio da ação das pessoas: de bons e maus. Coisas imensas no mundo. O grande-sertão é a forte arma. Deus é um gatilho?", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "Vida\" é noção que a gente completa seguida assim, mas só por lei duma idéia falsa. Cada dia é um dia.", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "O senhor não esteve lá. O senhor não escutou, em cada anoitecer, a lugúmem do canto da mãe-da-lua. O senhor não pode estabelecer em sua ideia a minha tristeza quinhoã. Até os pássaro, consoante os lugares, vão sendo muito diferentes. Ou são os tempos, travessia da gente?", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "Vivendo, se aprende; mas o que se aprende, mais, é só a fazer outras maiores perguntas.", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "Viver é negócio muito perigoso.", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "Raiva tampa o espaço do mêdo, assim como do mêdo raiva vem.", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "Conto o que fui e vi, no levantar do dia. Auroras.", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "Miguilim, Miguilim, vou ensinar o que agorinha eu sei, demais: é que a gente pode ficar sempre alegre, alegre, mesmo com toda coisa ruim que acontece acontecendo. A gente deve de poder ficar então mais alegre, mais alegre, por dentro!", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "Dito, eu às vezes tenho uma saudade de uma coisa que eu não sei o que é, nem de donde, me afrontando...", Author = "Guimarães Rosa" },
